-- C05 CRM collaboration. Financial and stock ledgers remain untouched.
ALTER TABLE crm.mobile_heads ADD COLUMN acl_version bigint NOT NULL DEFAULT 0;
CREATE TABLE crm.collaboration_objects(id uuid NOT NULL,company_id uuid NOT NULL REFERENCES core.companies(id),kind text NOT NULL CHECK(kind IN('NOTE','BOARD','VISIT')),customer_id uuid NOT NULL,branch_id uuid,product_id uuid,owner_id uuid NOT NULL REFERENCES identity.users(id),visibility text NOT NULL DEFAULT 'TEAM'CHECK(visibility IN('TEAM','PRIVATE','OFFICE')),state text NOT NULL,data jsonb NOT NULL CHECK(jsonb_typeof(data)='object'),version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,id),FOREIGN KEY(company_id,customer_id)REFERENCES crm.customers(company_id,id),FOREIGN KEY(company_id,branch_id)REFERENCES crm.customer_branches(company_id,id),FOREIGN KEY(company_id,product_id)REFERENCES catalog.products(company_id,id),CHECK((kind='NOTE'AND state IN('ACTIVE','DELETED'))OR(kind='BOARD'AND state IN('DISPLAYED','REMOVED','DELETED'))OR(kind='VISIT'AND state IN('OPEN','CLOSED','CANCELLED'))),CHECK(kind='NOTE'OR branch_id IS NOT NULL));
CREATE UNIQUE INDEX collaboration_one_open_visit ON crm.collaboration_objects(company_id,owner_id)WHERE kind='VISIT'AND state='OPEN';
CREATE INDEX ON crm.collaboration_objects(company_id,customer_id,kind,created_at,id);
CREATE TABLE crm.collaboration_history(company_id uuid NOT NULL,object_id uuid NOT NULL,version bigint NOT NULL,snapshot jsonb NOT NULL,actor_id uuid NOT NULL REFERENCES identity.users(id),action text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,object_id,version),FOREIGN KEY(company_id,object_id)REFERENCES crm.collaboration_objects(company_id,id));
CREATE TABLE crm.collaboration_changes(company_id uuid NOT NULL,sequence bigint NOT NULL,entity_type text NOT NULL,entity_id uuid NOT NULL,customer_id uuid NOT NULL,owner_id uuid,visibility text NOT NULL,version bigint NOT NULL,tombstone boolean NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,sequence),FOREIGN KEY(company_id,customer_id)REFERENCES crm.customers(company_id,id));
CREATE TABLE crm.branch_geocodes(company_id uuid NOT NULL,branch_id uuid NOT NULL,branch_version bigint NOT NULL,latitude numeric(10,7)NOT NULL CHECK(latitude BETWEEN -90 AND 90),longitude numeric(10,7)NOT NULL CHECK(longitude BETWEEN -180 AND 180),precision text NOT NULL CHECK(precision IN('ROOFTOP','RANGE_INTERPOLATED','GEOMETRIC_CENTER','APPROXIMATE','MANUAL')),source text NOT NULL CHECK(source IN('GOOGLE','MANUAL')),place_id text,reason text,expires_at timestamptz,version bigint NOT NULL DEFAULT 1,created_by uuid NOT NULL REFERENCES identity.users(id),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,branch_id),FOREIGN KEY(company_id,branch_id)REFERENCES crm.customer_branches(company_id,id));
CREATE TABLE crm.geocode_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),branch_id uuid NOT NULL,branch_version bigint NOT NULL,address jsonb NOT NULL,created_by uuid NOT NULL REFERENCES identity.users(id),state text NOT NULL DEFAULT 'PENDING'CHECK(state IN('PENDING','PROCESSING','RETRY','FAILED','STALE','SUCCEEDED')),attempts int NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 5),lease_token uuid,lease_until timestamptz,available_at timestamptz NOT NULL DEFAULT now(),last_error text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,branch_id,branch_version),FOREIGN KEY(company_id,branch_id)REFERENCES crm.customer_branches(company_id,id));
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['collaboration_objects','collaboration_history','collaboration_changes','branch_geocodes','geocode_jobs']LOOP EXECUTE format('ALTER TABLE crm.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE crm.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY company_scope ON crm.%I USING(company_id=core.current_company())WITH CHECK(company_id=core.current_company())',t);IF t IN('collaboration_history','collaboration_changes')THEN EXECUTE format('CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON crm.%I FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation()',t);END IF;END LOOP;END$$;
CREATE TRIGGER collaboration_version BEFORE UPDATE ON crm.collaboration_objects FOR EACH ROW EXECUTE FUNCTION core.touch_version();
CREATE TRIGGER geocode_version BEFORE UPDATE ON crm.branch_geocodes FOR EACH ROW EXECUTE FUNCTION core.touch_version();
INSERT INTO identity.permissions(code,description)VALUES('crm.collaboration.read','Read authorized customer collaboration objects'),('crm.notes.write','Maintain own customer notes'),('crm.boards.write','Maintain customer branch display boards'),('crm.visits.write','Capture own visit fixes and finish own sessions'),('crm.collaboration.manage','Office collaboration maintenance and visit cancellation'),('crm.maps.read','Read authorized branch map and navigation contracts'),('crm.maps.manage','Queue geocoding and confirm branch coordinates');
CREATE FUNCTION identity.seed_collaboration_roles(c uuid)RETURNS void LANGUAGE sql SET search_path=pg_catalog AS $$INSERT INTO identity.role_permissions(company_id,role_id,permission_code)SELECT c,r.id,p.code FROM identity.roles r CROSS JOIN identity.permissions p WHERE r.company_id=c AND((r.code IN('ADMIN','OFFICE','SALES')AND p.code IN('crm.collaboration.read','crm.notes.write','crm.boards.write','crm.visits.write','crm.maps.read'))OR(r.code IN('ADMIN','OFFICE')AND p.code IN('crm.collaboration.manage','crm.maps.manage')))ON CONFLICT DO NOTHING$$;
DO $$DECLARE c uuid;BEGIN FOR c IN SELECT id FROM core.companies LOOP PERFORM set_config('htt.company_id',c::text,true);PERFORM identity.seed_collaboration_roles(c);END LOOP;PERFORM set_config('htt.company_id','',true);END$$;
CREATE FUNCTION crm.collab_visible(p_id uuid)RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT EXISTS(SELECT 1 FROM crm.collaboration_objects o WHERE o.company_id=core.current_company()AND o.id=p_id AND crm.mobile_permission('crm.collaboration.read')AND crm.mobile_customer_visible(o.customer_id)AND(o.visibility='TEAM'OR o.owner_id=core.current_actor()OR o.visibility='OFFICE'AND crm.mobile_permission('crm.collaboration.manage'))AND(o.kind<>'VISIT'OR o.owner_id=core.current_actor()OR crm.mobile_permission('crm.collaboration.manage')))$$;
CREATE FUNCTION crm.require_collab(p_id uuid,p_write boolean DEFAULT false)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE o crm.collaboration_objects;BEGIN SELECT*INTO o FROM crm.collaboration_objects WHERE company_id=core.current_company()AND id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'CRM object unavailable' USING ERRCODE='HT404';END IF;IF NOT crm.collab_visible(p_id)THEN RAISE EXCEPTION 'CRM object access denied' USING ERRCODE='42501';END IF;IF p_write THEN PERFORM crm.require_mobile(CASE o.kind WHEN'NOTE'THEN'crm.notes.write'WHEN'BOARD'THEN'crm.boards.write'ELSE'crm.visits.write'END);IF o.owner_id<>core.current_actor()AND NOT crm.mobile_permission('crm.collaboration.manage')THEN RAISE EXCEPTION 'Only author or office manager may maintain this object' USING ERRCODE='42501';END IF;END IF;END$$;
CREATE FUNCTION crm.collab_json(p_id uuid)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_collab(p_id);RETURN(SELECT jsonb_build_object('id',o.id,'kind',o.kind,'customerId',o.customer_id,'branchId',o.branch_id,'productId',o.product_id,'ownerId',o.owner_id,'visibility',o.visibility,'state',o.state,'version',o.version,'data',CASE WHEN o.state='DELETED'THEN NULL ELSE o.data END,'createdAt',o.created_at,'updatedAt',o.updated_at)FROM crm.collaboration_objects o WHERE o.company_id=core.current_company()AND o.id=p_id);END$$;
CREATE FUNCTION crm.validate_fix(p jsonb)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN
 IF jsonb_typeof(p)IS DISTINCT FROM'object'OR(p->>'latitude')IS NULL OR(p->>'longitude')IS NULL OR(p->>'accuracyMetres')IS NULL OR(p->>'capturedAt')IS NULL OR(p->>'latitude')::numeric NOT BETWEEN -90 AND 90 OR(p->>'longitude')::numeric NOT BETWEEN -180 AND 180 OR(p->>'accuracyMetres')::numeric NOT BETWEEN 1 AND 1000 OR(p->>'capturedAt')::timestamptz<now()-interval '7 days'OR(p->>'capturedAt')::timestamptz>now()+interval '5 minutes'THEN RAISE EXCEPTION 'Valid position, accuracy 1..1000m and capture time within past 7 days required' USING ERRCODE='HR422';END IF;
END$$;
CREATE FUNCTION crm.emit_collab(p_id uuid,p_action text)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE o crm.collaboration_objects;s bigint;j jsonb;BEGIN SELECT*INTO o FROM crm.collaboration_objects WHERE company_id=core.current_company()AND id=p_id;j:=crm.collab_json(p_id);INSERT INTO crm.collaboration_history(company_id,object_id,version,snapshot,actor_id,action)VALUES(o.company_id,o.id,o.version,j,core.current_actor(),p_action);UPDATE crm.mobile_heads SET sequence=sequence+1 WHERE company_id=o.company_id RETURNING sequence INTO s;INSERT INTO crm.collaboration_changes(company_id,sequence,entity_type,entity_id,customer_id,owner_id,visibility,version,tombstone,snapshot)VALUES(o.company_id,s,o.kind,o.id,o.customer_id,o.owner_id,o.visibility,o.version,o.state='DELETED',j);END$$;
CREATE FUNCTION crm.validate_collab_data(p_kind text,p_action text,p_data jsonb)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE allowed text[];BEGIN
 IF jsonb_typeof(p_data)IS DISTINCT FROM'object'OR pg_column_size(p_data)>20000 THEN RAISE EXCEPTION 'Bounded object payload required' USING ERRCODE='HR422';END IF;
 allowed:=CASE WHEN p_action IN('REMOVE','CANCEL')THEN ARRAY['reason']WHEN p_action='DELETE'THEN ARRAY[]::text[]WHEN p_action='CHECKOUT'THEN ARRAY['checkOut','notes']WHEN p_kind='NOTE'THEN ARRAY['text','visibility']WHEN p_kind='BOARD'THEN ARRAY['title','placedAt','productId','description']ELSE ARRAY['checkIn','purpose']END;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_data)k WHERE NOT(k=ANY(allowed)))OR coalesce(length(p_data->>'description'),0)>2000 OR coalesce(length(p_data->>'purpose'),0)>2000 OR coalesce(length(p_data->>'notes'),0)>2000 THEN RAISE EXCEPTION 'Unexpected or oversized collaboration payload' USING ERRCODE='HR422';END IF;
END$$;
CREATE FUNCTION crm.collab_command(p_id uuid,p_kind text,p_customer uuid,p_branch uuid,p_action text,p_version bigint,p_data jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE c uuid:=core.current_company();o crm.collaboration_objects;vis text;initial_state text;prod uuid;BEGIN
 PERFORM crm.validate_collab_data(p_kind,p_action,p_data);
 IF p_action='CREATE'THEN PERFORM crm.require_mobile('crm.collaboration.read');PERFORM crm.require_mobile(CASE p_kind WHEN'NOTE'THEN'crm.notes.write'WHEN'BOARD'THEN'crm.boards.write'WHEN'VISIT'THEN'crm.visits.write'ELSE'unsupported'END);IF NOT crm.mobile_customer_visible(p_customer)OR p_customer IS NULL THEN RAISE EXCEPTION 'Customer access denied' USING ERRCODE='42501';END IF;ELSE PERFORM crm.require_collab(p_id,true);END IF;
 PERFORM crm.lock_mobile_head();
 IF p_action='CREATE'THEN
  PERFORM crm.require_mobile('crm.collaboration.read');PERFORM crm.require_mobile(CASE p_kind WHEN'NOTE'THEN'crm.notes.write'WHEN'BOARD'THEN'crm.boards.write'ELSE'crm.visits.write'END);IF NOT crm.mobile_customer_visible(p_customer)THEN RAISE EXCEPTION 'Customer access changed' USING ERRCODE='42501';END IF;
  IF p_id IS NULL OR p_id='00000000-0000-0000-0000-000000000000'OR p_kind NOT IN('NOTE','BOARD','VISIT')OR p_kind<>'NOTE'AND p_branch IS NULL OR p_branch IS NOT NULL AND NOT EXISTS(SELECT 1 FROM crm.customer_branches WHERE company_id=c AND id=p_branch AND customer_id=p_customer AND active)THEN RAISE EXCEPTION 'Valid object and active branch belonging to customer required' USING ERRCODE='HR422';END IF;
  IF EXISTS(SELECT 1 FROM crm.collaboration_objects WHERE company_id=c AND id=p_id)OR EXISTS(SELECT 1 FROM platform.documents WHERE company_id=c AND id=p_id)THEN RAISE EXCEPTION 'Object ID already exists' USING ERRCODE='HR409';END IF;
  vis:=CASE WHEN p_kind='NOTE'THEN p_data->>'visibility'ELSE'TEAM'END;initial_state:=CASE p_kind WHEN'NOTE'THEN'ACTIVE'WHEN'BOARD'THEN'DISPLAYED'ELSE'OPEN'END;
  IF p_kind='VISIT'THEN PERFORM crm.validate_fix(p_data->'checkIn');IF EXISTS(SELECT 1 FROM crm.collaboration_objects WHERE company_id=c AND owner_id=core.current_actor()AND kind='VISIT'AND state='OPEN')THEN RAISE EXCEPTION 'An open visit already exists; finish or cancel it first' USING ERRCODE='HR409';END IF;
  ELSIF p_kind='BOARD'THEN prod:=(p_data->>'productId')::uuid;IF prod IS NOT NULL AND NOT EXISTS(SELECT 1 FROM catalog.products WHERE company_id=c AND id=prod)THEN RAISE EXCEPTION 'Board product unavailable' USING ERRCODE='HR422';END IF;
  END IF;
  IF vis IS NULL OR vis NOT IN('TEAM','PRIVATE','OFFICE')OR p_kind='NOTE'AND coalesce(length(btrim(p_data->>'text')),0)NOT BETWEEN 1 AND 10000 OR p_kind='BOARD'AND(coalesce(length(btrim(p_data->>'title')),0)NOT BETWEEN 1 AND 200 OR(p_data->>'placedAt')IS NULL OR(p_data->>'placedAt')::timestamptz>now()+interval '5 minutes')OR pg_column_size(p_data)>20000 THEN RAISE EXCEPTION 'Invalid collaboration details' USING ERRCODE='HR422';END IF;
  INSERT INTO crm.collaboration_objects(id,company_id,kind,customer_id,branch_id,product_id,owner_id,visibility,state,data)VALUES(p_id,c,p_kind,p_customer,p_branch,prod,core.current_actor(),vis,initial_state,p_data||CASE WHEN p_kind='VISIT'THEN jsonb_build_object('checkInReceivedAt',now())ELSE'{}'::jsonb END);
  INSERT INTO platform.documents(id,company_id,document_type,business_date,state,created_by)VALUES(p_id,c,'CRM_'||p_kind,(SELECT(now()AT TIME ZONE timezone)::date FROM core.companies WHERE id=c),'DRAFT',core.current_actor());
 ELSE
  PERFORM crm.require_collab(p_id,true);SELECT*INTO o FROM crm.collaboration_objects WHERE company_id=c AND id=p_id FOR UPDATE;
  IF o.version IS DISTINCT FROM p_version OR o.state='DELETED'THEN RAISE EXCEPTION 'Object version/state conflict' USING ERRCODE='HR409';END IF;
  IF p_action='UPDATE'AND o.kind IN('NOTE','BOARD')THEN
   vis:=CASE WHEN o.kind='NOTE'THEN p_data->>'visibility'ELSE'TEAM'END;
   IF vis IS NULL OR vis NOT IN('TEAM','PRIVATE','OFFICE')OR o.kind='NOTE'AND coalesce(length(btrim(p_data->>'text')),0)NOT BETWEEN 1 AND 10000 OR o.kind='BOARD'AND(coalesce(length(btrim(p_data->>'title')),0)NOT BETWEEN 1 AND 200 OR(p_data->>'productId')::uuid IS DISTINCT FROM o.product_id OR(p_data->>'placedAt')IS DISTINCT FROM(o.data->>'placedAt'))OR pg_column_size(p_data)>20000 THEN RAISE EXCEPTION 'Invalid update; board product and placement date are immutable' USING ERRCODE='HR422';END IF;
   IF vis<>o.visibility THEN UPDATE crm.mobile_heads SET acl_version=acl_version+1 WHERE company_id=c;END IF;UPDATE crm.collaboration_objects SET data=p_data,visibility=vis WHERE company_id=c AND id=p_id;
  ELSIF p_action='DELETE'AND o.kind IN('NOTE','BOARD')THEN UPDATE crm.collaboration_objects SET state='DELETED',data='{}'WHERE company_id=c AND id=p_id;UPDATE crm.mobile_heads SET acl_version=acl_version+1 WHERE company_id=c;
  ELSIF p_action='REMOVE'AND o.kind='BOARD'AND o.state='DISPLAYED'THEN IF coalesce(length(btrim(p_data->>'reason')),0)NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Removal reason required' USING ERRCODE='HR422';END IF;UPDATE crm.collaboration_objects SET state='REMOVED',data=data||p_data||jsonb_build_object('removedAt',now())WHERE company_id=c AND id=p_id;
  ELSIF p_action='CHECKOUT'AND o.kind='VISIT'AND o.state='OPEN'THEN IF o.owner_id<>core.current_actor()THEN RAISE EXCEPTION 'Only original visitor may check out' USING ERRCODE='42501';END IF;PERFORM crm.validate_fix(p_data->'checkOut');IF(p_data#>>'{checkOut,capturedAt}')::timestamptz<(o.data#>>'{checkIn,capturedAt}')::timestamptz THEN RAISE EXCEPTION 'Checkout precedes check-in' USING ERRCODE='HR422';END IF;UPDATE crm.collaboration_objects SET state='CLOSED',data=data||p_data||jsonb_build_object('checkOutReceivedAt',now())WHERE company_id=c AND id=p_id;
  ELSIF p_action='CANCEL'AND o.kind='VISIT'AND o.state='OPEN'THEN IF coalesce(length(btrim(p_data->>'reason')),0)NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Cancellation reason required' USING ERRCODE='HR422';END IF;UPDATE crm.collaboration_objects SET state='CANCELLED',data=data||jsonb_build_object('cancelReason',p_data->>'reason','cancelledAt',now(),'cancelledBy',core.current_actor())WHERE company_id=c AND id=p_id;
  ELSE RAISE EXCEPTION 'Unsupported operation for current object state' USING ERRCODE='HR409';END IF;
  UPDATE platform.documents d SET state=d.state WHERE company_id=c AND id=p_id;
 END IF;
 PERFORM crm.emit_collab(p_id,p_action);RETURN crm.collab_json(p_id);
END$$;
CREATE FUNCTION crm.collab_history(p_id uuid)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_collab(p_id);IF EXISTS(SELECT 1 FROM crm.collaboration_objects WHERE company_id=core.current_company()AND id=p_id AND state='DELETED')THEN RAISE EXCEPTION 'Deleted object unavailable' USING ERRCODE='HT404';END IF;RETURN(SELECT coalesce(jsonb_agg(jsonb_build_object('version',h.version,'action',h.action,'actorId',h.actor_id,'createdAt',h.created_at,'snapshot',h.snapshot)ORDER BY h.version),'[]')FROM crm.collaboration_history h WHERE h.company_id=core.current_company()AND h.object_id=p_id AND(h.snapshot->>'visibility'='TEAM'OR(h.snapshot->>'ownerId')::uuid=core.current_actor()OR h.snapshot->>'visibility'='OFFICE'AND crm.mobile_permission('crm.collaboration.manage')));END$$;
CREATE FUNCTION crm.collab_event_visible(p_type text,p_id uuid,p_owner uuid,p_visibility text,p_tombstone boolean)RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT crm.collab_visible(p_id)AND(p_visibility='TEAM'OR p_owner=core.current_actor()OR p_visibility='OFFICE'AND crm.mobile_permission('crm.collaboration.manage'))AND(p_tombstone OR NOT EXISTS(SELECT 1 FROM crm.collaboration_objects WHERE company_id=core.current_company()AND id=p_id AND state='DELETED'))$$;
CREATE FUNCTION crm.collab_push(p_device uuid,p_operation uuid,p_sequence bigint,p_request jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE c uuid:=core.current_company();dev crm.mobile_devices;old crm.mobile_operations;res jsonb;target uuid:=(p_request->>'id')::uuid;act text:=p_request->>'action';BEGIN
 PERFORM crm.require_mobile_device(p_device);PERFORM crm.require_mobile('crm.collaboration.read');
 IF act='CREATE'THEN IF NOT crm.mobile_customer_visible((p_request->>'customerId')::uuid)THEN RAISE EXCEPTION 'Customer access denied' USING ERRCODE='42501';END IF;PERFORM crm.require_mobile(CASE p_request->>'kind'WHEN'NOTE'THEN'crm.notes.write'WHEN'BOARD'THEN'crm.boards.write'WHEN'VISIT'THEN'crm.visits.write'ELSE'unsupported'END);ELSE PERFORM crm.require_collab(target,true);END IF;
 PERFORM crm.lock_mobile_head();SELECT*INTO dev FROM crm.mobile_devices WHERE company_id=c AND id=p_device FOR UPDATE;PERFORM crm.require_mobile_device(p_device);
 IF act<>'CREATE'THEN PERFORM crm.require_collab(target,true);ELSE IF NOT crm.mobile_customer_visible((p_request->>'customerId')::uuid)THEN RAISE EXCEPTION 'Customer scope changed' USING ERRCODE='42501';END IF;END IF;
 SELECT*INTO old FROM crm.mobile_operations WHERE company_id=c AND operation_id=p_operation;
 IF FOUND THEN IF old.device_id<>p_device OR old.device_sequence<>p_sequence OR old.request<>p_request THEN RAISE EXCEPTION 'Operation identity reused' USING ERRCODE='HR409';END IF;RETURN old.response;END IF;
 IF p_sequence IS NULL OR p_sequence<>dev.last_sequence+1 OR p_operation IS NULL THEN RAISE EXCEPTION 'Device sequence gap or conflicting replay' USING ERRCODE='HR409';END IF;
 BEGIN res:=crm.collab_command(target,p_request->>'kind',(p_request->>'customerId')::uuid,(p_request->>'branchId')::uuid,act,(p_request->>'version')::bigint,p_request->'data');res:=jsonb_build_object('status','APPLIED','entity',res);
 EXCEPTION WHEN SQLSTATE'HR409'THEN res:=jsonb_build_object('status','CONFLICT','id',target,'serverVersion',(SELECT version FROM crm.collaboration_objects WHERE company_id=c AND id=target AND crm.collab_visible(target)));END;
 UPDATE crm.mobile_devices SET last_sequence=p_sequence WHERE company_id=c AND id=p_device;INSERT INTO crm.mobile_operations(company_id,operation_id,device_id,device_sequence,request,response)VALUES(c,p_operation,p_device,p_sequence,p_request,res);RETURN res;
END$$;
-- Drafts get the same private attachment registry; existing rows are backfilled without changing their data/version.
CREATE FUNCTION crm.sync_draft_registry()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN IF TG_OP='INSERT'THEN INSERT INTO platform.documents(id,company_id,document_type,business_date,state,version,created_by)VALUES(NEW.id,NEW.company_id,'CRM_DRAFT',(SELECT(NEW.created_at AT TIME ZONE timezone)::date FROM core.companies WHERE id=NEW.company_id),'DRAFT',NEW.version,NEW.owner_id);ELSE UPDATE platform.documents d SET state=d.state WHERE d.company_id=NEW.company_id AND d.id=NEW.id;END IF;RETURN NEW;END$$;
CREATE TRIGGER crm_draft_registry AFTER INSERT OR UPDATE ON crm.mobile_drafts FOR EACH ROW EXECUTE FUNCTION crm.sync_draft_registry();
DO $$DECLARE c uuid;BEGIN FOR c IN SELECT id FROM core.companies LOOP PERFORM set_config('htt.company_id',c::text,true);INSERT INTO platform.documents(id,company_id,document_type,business_date,state,version,created_by)SELECT id,company_id,'CRM_DRAFT',(SELECT(d.created_at AT TIME ZONE timezone)::date FROM core.companies WHERE id=c),'DRAFT',version,owner_id FROM crm.mobile_drafts d WHERE company_id=c;SET CONSTRAINTS ALL IMMEDIATE;SET CONSTRAINTS ALL DEFERRED;END LOOP;PERFORM set_config('htt.company_id','',true);END$$;
CREATE FUNCTION crm.require_crm_file(p_id uuid,p_write boolean)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE d crm.mobile_drafts;o crm.collaboration_objects;BEGIN
 IF p_write THEN PERFORM crm.lock_mobile_head();END IF;
 SELECT*INTO d FROM crm.mobile_drafts WHERE company_id=core.current_company()AND id=p_id;
 IF FOUND THEN PERFORM crm.require_mobile_draft(p_id,CASE WHEN p_write THEN'WRITE'ELSE'READ'END);IF d.state='DELETED'OR p_write AND d.state<>'DRAFT'THEN RAISE EXCEPTION 'Draft attachments unavailable in this state' USING ERRCODE='HR409';END IF;
 ELSE PERFORM crm.require_collab(p_id,p_write);SELECT*INTO o FROM crm.collaboration_objects WHERE company_id=core.current_company()AND id=p_id;IF o.state='DELETED'THEN RAISE EXCEPTION 'Deleted CRM object unavailable' USING ERRCODE='HT404';END IF;END IF;
END$$;
-- Attachment notifications contain only identity/state. Bytes remain behind current entity access checks.
CREATE FUNCTION crm.emit_attachment(p_document uuid,p_file uuid)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE s bigint;customer uuid;actor uuid;vis text;BEGIN
 SELECT customer_id,owner_id,visibility INTO customer,actor,vis FROM crm.collaboration_objects WHERE company_id=core.current_company()AND id=p_document;
 IF NOT FOUND THEN SELECT customer_id,owner_id,'DRAFT'INTO customer,actor,vis FROM crm.mobile_drafts WHERE company_id=core.current_company()AND id=p_document;END IF;
 IF customer IS NULL THEN IF EXISTS(SELECT 1 FROM crm.mobile_drafts WHERE company_id=core.current_company()AND id=p_document)THEN PERFORM crm.lock_mobile_head();PERFORM crm.emit_draft(p_document);END IF;RETURN;END IF;PERFORM crm.lock_mobile_head();UPDATE crm.mobile_heads SET sequence=sequence+1 WHERE company_id=core.current_company()RETURNING sequence INTO s;
 INSERT INTO crm.collaboration_changes(company_id,sequence,entity_type,entity_id,customer_id,owner_id,visibility,version,tombstone,snapshot)SELECT f.company_id,s,'ATTACHMENT',p_document,customer,actor,vis,f.version,a.revoked_at IS NOT NULL,jsonb_build_object('id',p_file,'parentId',p_document,'state',f.state,'version',f.version,'revoked',a.revoked_at IS NOT NULL)FROM platform.files f JOIN platform.file_assets a ON a.company_id=f.company_id AND a.file_id=f.id WHERE f.company_id=core.current_company()AND f.id=p_file;
END$$;
CREATE FUNCTION crm.file_changed()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE doc uuid;fid uuid;BEGIN fid:=coalesce(to_jsonb(NEW)->>'file_id',to_jsonb(NEW)->>'id')::uuid;SELECT document_id INTO doc FROM platform.file_assets WHERE company_id=NEW.company_id AND file_id=fid;IF EXISTS(SELECT 1 FROM platform.documents WHERE company_id=NEW.company_id AND id=doc AND document_type LIKE'CRM_%')THEN PERFORM crm.emit_attachment(doc,fid);END IF;RETURN NEW;END$$;
CREATE TRIGGER crm_attachment_change AFTER INSERT OR UPDATE ON platform.file_assets FOR EACH ROW EXECUTE FUNCTION crm.file_changed();
CREATE TRIGGER crm_file_change AFTER UPDATE ON platform.files FOR EACH ROW EXECUTE FUNCTION crm.file_changed();
CREATE FUNCTION crm.require_branch(p_branch uuid,p_manage boolean DEFAULT false)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE customer uuid;BEGIN PERFORM crm.require_mobile(CASE WHEN p_manage THEN'crm.maps.manage'ELSE'crm.maps.read'END);SELECT customer_id INTO customer FROM crm.customer_branches WHERE company_id=core.current_company()AND id=p_branch AND active;IF NOT FOUND THEN RAISE EXCEPTION 'Active branch unavailable' USING ERRCODE='HT404';END IF;IF NOT crm.mobile_customer_visible(customer)THEN RAISE EXCEPTION 'Customer map access denied' USING ERRCODE='42501';END IF;RETURN customer;END$$;
CREATE FUNCTION crm.queue_geocode(p_branch uuid,p_version bigint)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE b crm.customer_branches;job uuid;BEGIN PERFORM crm.require_branch(p_branch,true);PERFORM crm.lock_mobile_head();PERFORM crm.require_branch(p_branch,true);SELECT*INTO b FROM crm.customer_branches WHERE company_id=core.current_company()AND id=p_branch FOR SHARE;IF b.version IS DISTINCT FROM p_version THEN RAISE EXCEPTION 'Branch changed; refresh address' USING ERRCODE='HR409';END IF;
 INSERT INTO crm.geocode_jobs(company_id,branch_id,branch_version,address,created_by)VALUES(b.company_id,b.id,b.version,jsonb_build_object('address',concat_ws(', ',b.address_line1,b.suburb,b.state,b.postcode,b.country),'country',b.country),core.current_actor())ON CONFLICT DO NOTHING RETURNING id INTO job;IF job IS NULL THEN SELECT id INTO job FROM crm.geocode_jobs WHERE company_id=b.company_id AND branch_id=b.id AND branch_version=b.version;UPDATE crm.geocode_jobs SET state='PENDING',attempts=0,available_at=now(),last_error=NULL,created_by=core.current_actor()WHERE id=job AND state='SUCCEEDED'AND NOT EXISTS(SELECT 1 FROM crm.branch_geocodes WHERE company_id=b.company_id AND branch_id=b.id AND branch_version=b.version AND(expires_at IS NULL OR expires_at>now()));END IF;PERFORM crm.emit_geocode(p_branch);RETURN job;
END$$;
CREATE FUNCTION crm.geocode_view(p_id uuid)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE j crm.geocode_jobs;BEGIN SELECT*INTO j FROM crm.geocode_jobs WHERE company_id=core.current_company()AND id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'Geocode job unavailable' USING ERRCODE='HT404';END IF;PERFORM crm.require_branch(j.branch_id,true);RETURN jsonb_build_object('id',j.id,'branchId',j.branch_id,'branchVersion',j.branch_version,'state',j.state,'attempts',j.attempts,'lastError',j.last_error);END$$;
CREATE FUNCTION crm.retry_geocode(p_id uuid)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE j crm.geocode_jobs;BEGIN SELECT*INTO j FROM crm.geocode_jobs WHERE company_id=core.current_company()AND id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'Geocode job unavailable' USING ERRCODE='HT404';END IF;PERFORM crm.require_branch(j.branch_id,true);PERFORM crm.lock_mobile_head();PERFORM crm.require_branch(j.branch_id,true);UPDATE crm.geocode_jobs SET state='PENDING',attempts=0,available_at=now(),last_error=NULL,created_by=core.current_actor()WHERE id=p_id AND state='FAILED'AND branch_version=(SELECT version FROM crm.customer_branches WHERE company_id=j.company_id AND id=j.branch_id);IF NOT FOUND THEN RAISE EXCEPTION 'Only failed current-address jobs can retry' USING ERRCODE='HR409';END IF;PERFORM crm.emit_geocode(j.branch_id);END$$;
CREATE FUNCTION crm.emit_geocode(p_branch uuid)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE s bigint;b crm.customer_branches;BEGIN PERFORM crm.lock_mobile_head();SELECT*INTO b FROM crm.customer_branches WHERE company_id=core.current_company()AND id=p_branch;UPDATE crm.mobile_heads SET sequence=sequence+1 WHERE company_id=b.company_id RETURNING sequence INTO s;INSERT INTO crm.collaboration_changes(company_id,sequence,entity_type,entity_id,customer_id,visibility,version,tombstone,snapshot)VALUES(b.company_id,s,'BRANCH_GEO',b.id,b.customer_id,'TEAM',b.version,NOT b.active,jsonb_build_object('branchId',b.id,'branchVersion',b.version,'refreshRequired',true));END$$;
CREATE FUNCTION crm.set_branch_coordinates(p_branch uuid,p_version bigint,p_lat numeric,p_lng numeric,p_reason text)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_branch(p_branch,true);PERFORM crm.lock_mobile_head();PERFORM crm.require_branch(p_branch,true);PERFORM 1 FROM crm.customer_branches WHERE company_id=core.current_company()AND id=p_branch AND version=p_version FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Branch changed' USING ERRCODE='HR409';END IF;IF p_lat IS NULL OR p_lng IS NULL OR p_lat NOT BETWEEN -90 AND 90 OR p_lng NOT BETWEEN -180 AND 180 OR coalesce(length(btrim(p_reason)),0)NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Coordinates and evidence reason required' USING ERRCODE='HR422';END IF;
 INSERT INTO crm.branch_geocodes(company_id,branch_id,branch_version,latitude,longitude,precision,source,reason,created_by)VALUES(core.current_company(),p_branch,p_version,p_lat,p_lng,'MANUAL','MANUAL',p_reason,core.current_actor())ON CONFLICT(company_id,branch_id)DO UPDATE SET branch_version=excluded.branch_version,latitude=excluded.latitude,longitude=excluded.longitude,precision='MANUAL',source='MANUAL',place_id=NULL,reason=excluded.reason,expires_at=NULL;PERFORM crm.emit_geocode(p_branch);END$$;
CREATE FUNCTION crm.claim_geocode()RETURNS TABLE(job_id uuid,lease uuid)LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE j crm.geocode_jobs;tok uuid;BEGIN
 DELETE FROM crm.branch_geocodes WHERE source='GOOGLE'AND expires_at<=now();
 UPDATE crm.geocode_jobs SET state='FAILED',last_error='attempts_exhausted',lease_token=NULL,lease_until=NULL WHERE state='PROCESSING'AND lease_until<now()AND attempts>=5;
 SELECT*INTO j FROM crm.geocode_jobs WHERE(state IN('PENDING','RETRY')AND available_at<=now()OR state='PROCESSING'AND lease_until<now())AND attempts<5 ORDER BY available_at,created_at,id FOR UPDATE SKIP LOCKED LIMIT 1;IF NOT FOUND THEN RETURN;END IF;tok:=gen_random_uuid();UPDATE crm.geocode_jobs SET state='PROCESSING',attempts=attempts+1,lease_token=tok,lease_until=now()+interval '2 minutes'WHERE id=j.id;RETURN QUERY SELECT j.id,tok;END$$;
CREATE FUNCTION crm.load_geocode(p_id uuid,p_lease uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE j crm.geocode_jobs;BEGIN SELECT*INTO j FROM crm.geocode_jobs WHERE id=p_id AND state='PROCESSING'AND lease_token=p_lease AND lease_until>now();IF NOT FOUND THEN RAISE EXCEPTION 'Geocode lease unavailable' USING ERRCODE='HR409';END IF;PERFORM set_config('htt.company_id',j.company_id::text,true);PERFORM set_config('htt.actor_id',j.created_by::text,true);PERFORM crm.require_branch(j.branch_id,true);IF NOT EXISTS(SELECT 1 FROM crm.customer_branches WHERE company_id=j.company_id AND id=j.branch_id AND version=j.branch_version)THEN RAISE EXCEPTION 'Address changed' USING ERRCODE='HR409';END IF;RETURN j.address;END$$;
CREATE FUNCTION crm.finish_geocode(p_id uuid,p_lease uuid,p_state text,p_error text,p_result jsonb)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE j crm.geocode_jobs;st text:=p_state;err text:=p_error;BEGIN SELECT*INTO j FROM crm.geocode_jobs WHERE id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'Geocode job unavailable' USING ERRCODE='HR409';END IF;PERFORM set_config('htt.company_id',j.company_id::text,true);PERFORM set_config('htt.actor_id',j.created_by::text,true);
 PERFORM crm.lock_mobile_head();SELECT*INTO j FROM crm.geocode_jobs WHERE id=p_id FOR UPDATE;IF j.state<>'PROCESSING'OR j.lease_token IS DISTINCT FROM p_lease OR j.lease_until<=now()THEN RAISE EXCEPTION 'Stale geocode lease' USING ERRCODE='HR409';END IF;
 IF st NOT IN('SUCCEEDED','RETRY','FAILED','STALE')THEN RAISE EXCEPTION 'Invalid geocode completion' USING ERRCODE='HR422';END IF;
 BEGIN PERFORM crm.require_branch(j.branch_id,true);EXCEPTION WHEN insufficient_privilege OR SQLSTATE'HT404'THEN st:='FAILED';err:='geocode_access_changed';END;
 PERFORM 1 FROM crm.customer_branches WHERE company_id=j.company_id AND id=j.branch_id AND version=j.branch_version FOR SHARE;IF NOT FOUND THEN st:='STALE';err:='address_changed';END IF;
 IF st='SUCCEEDED'THEN IF(p_result->>'latitude')IS NULL OR(p_result->>'longitude')IS NULL OR(p_result->>'latitude')::numeric NOT BETWEEN -90 AND 90 OR(p_result->>'longitude')::numeric NOT BETWEEN -180 AND 180 OR coalesce(p_result->>'precision','')NOT IN('ROOFTOP','RANGE_INTERPOLATED','GEOMETRIC_CENTER','APPROXIMATE')OR coalesce(length(p_result->>'placeId'),0)NOT BETWEEN 1 AND 300 THEN RAISE EXCEPTION 'Invalid geocoding result' USING ERRCODE='HR422';END IF;
 -- A late automatic result cannot overwrite staff-confirmed coordinates for this address version.
 IF NOT EXISTS(SELECT 1 FROM crm.branch_geocodes WHERE company_id=j.company_id AND branch_id=j.branch_id AND branch_version=j.branch_version AND source='MANUAL')THEN INSERT INTO crm.branch_geocodes(company_id,branch_id,branch_version,latitude,longitude,precision,source,place_id,expires_at,created_by)VALUES(j.company_id,j.branch_id,j.branch_version,(p_result->>'latitude')::numeric,(p_result->>'longitude')::numeric,p_result->>'precision','GOOGLE',p_result->>'placeId',now()+interval '30 days',j.created_by)ON CONFLICT(company_id,branch_id)DO UPDATE SET branch_version=excluded.branch_version,latitude=excluded.latitude,longitude=excluded.longitude,precision=excluded.precision,source='GOOGLE',place_id=excluded.place_id,reason=NULL,expires_at=excluded.expires_at;END IF;PERFORM crm.emit_geocode(j.branch_id);END IF;
 UPDATE crm.geocode_jobs SET state=CASE WHEN st='RETRY'AND attempts>=5 THEN'FAILED'ELSE st END,last_error=left(err,100),lease_token=NULL,lease_until=NULL,available_at=now()+make_interval(secs=>power(2,j.attempts)::int)WHERE id=p_id;
 IF st<>'SUCCEEDED'THEN PERFORM crm.emit_geocode(j.branch_id);END IF;
 INSERT INTO platform.audit_events(company_id,actor_id,action,entity_type,entity_id,request_id,details)VALUES(j.company_id,j.created_by,'crm.geocode_finished','geocode_job',j.id,'geocode-worker',jsonb_build_object('state',st,'error',err));
END$$;

CREATE OR REPLACE FUNCTION crm.mobile_auth_hash()RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT md5((coalesce((SELECT string_agg(x,'|'ORDER BY x)FROM(SELECT rp.permission_code AS x FROM identity.memberships m JOIN identity.membership_roles mr ON mr.company_id=m.company_id AND mr.membership_id=m.id JOIN identity.role_permissions rp ON rp.company_id=mr.company_id AND rp.role_id=mr.role_id WHERE m.company_id=core.current_company()AND m.user_id=core.current_actor()AND m.active UNION SELECT a.id::text||':'||a.version::text FROM identity.customer_assignments a JOIN identity.memberships m ON m.company_id=a.company_id AND m.id=a.membership_id WHERE a.company_id=core.current_company()AND m.user_id=core.current_actor()AND m.active)s),''))||':'||coalesce((SELECT acl_version::text FROM crm.mobile_heads WHERE company_id=core.current_company()),'0'))$$;

CREATE OR REPLACE FUNCTION crm.mobile_pull(p_device uuid,p_after bigint,p_auth text,p_limit int DEFAULT 100)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE high bigint;next_seq bigint;items jsonb;auth text;dev crm.mobile_devices;BEGIN
 PERFORM crm.require_mobile_device(p_device);IF p_after<0 OR p_limit NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid sync page' USING ERRCODE='HR422';END IF;
 -- Commit-ordered head plus device epoch: scope changes, expiry and reset invalidate old cursors.
 PERFORM crm.lock_mobile_head();SELECT*INTO dev FROM crm.mobile_devices WHERE company_id=core.current_company()AND id=p_device FOR UPDATE;PERFORM crm.require_mobile_device(p_device);
 IF p_after=0 THEN UPDATE crm.mobile_devices SET sync_epoch=gen_random_uuid(),cursor_expires_at=now()+interval '30 days'WHERE company_id=core.current_company()AND id=p_device RETURNING*INTO dev;END IF;auth:=md5(crm.mobile_auth_hash()||dev.sync_epoch::text);
 IF p_after>0 AND(p_auth IS DISTINCT FROM auth OR dev.cursor_expires_at<=now())THEN RAISE EXCEPTION 'Cursor expired or authorization changed; discard cached CRM objects and restart at zero' USING ERRCODE='HR409';END IF;
 SELECT sequence INTO high FROM crm.mobile_heads WHERE company_id=core.current_company();IF p_after>high THEN RAISE EXCEPTION 'Cursor ahead of server; reset required' USING ERRCODE='HR409';END IF;
 SELECT coalesce(max(sequence),p_after),coalesce(jsonb_agg(payload ORDER BY sequence)FILTER(WHERE allowed),'[]')INTO next_seq,items FROM(
 SELECT sequence,payload,allowed FROM(
 SELECT d.sequence,jsonb_build_object('sequence',d.sequence,'entityType','DRAFT','tombstone',d.tombstone,'draft',d.snapshot)AS payload,(d.owner_id=core.current_actor()OR crm.mobile_reviewer())AND crm.mobile_customer_visible(d.customer_id)AS allowed FROM crm.mobile_changes d WHERE d.company_id=core.current_company()AND d.sequence>p_after
 UNION ALL
 SELECT e.sequence,jsonb_build_object('sequence',e.sequence,'entityType',e.entity_type,'tombstone',e.tombstone,'entity',e.snapshot),crm.mobile_customer_visible(e.customer_id)AND CASE WHEN e.entity_type='BRANCH_GEO'THEN crm.mobile_permission('crm.maps.read')WHEN e.entity_type='ATTACHMENT'AND e.visibility='DRAFT'THEN crm.mobile_permission('crm.drafts.read')AND(e.owner_id=core.current_actor()OR crm.mobile_reviewer())AND EXISTS(SELECT 1 FROM crm.mobile_drafts d WHERE d.company_id=e.company_id AND d.id=e.entity_id AND d.state<>'DELETED')ELSE crm.collab_event_visible(e.entity_type,e.entity_id,e.owner_id,e.visibility,e.tombstone)END FROM crm.collaboration_changes e WHERE e.company_id=core.current_company()AND e.sequence>p_after
 )u ORDER BY sequence LIMIT p_limit)s;RETURN jsonb_build_object('items',items,'nextSequence',next_seq,'auth',auth,'hasMore',next_seq<high,'resetRequired',false,'cursorExpiresAt',dev.cursor_expires_at);
END$$;

CREATE OR REPLACE FUNCTION platform.require_document_access(doc uuid,action text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE typ text;customer uuid;required text;BEGIN
 required:=CASE action WHEN 'READ' THEN 'documents.files.read' WHEN 'PDF' THEN 'documents.pdf.request' WHEN 'EMAIL' THEN 'documents.email.send' WHEN 'EXPORT' THEN 'reports.operating.export' WHEN 'UPLOAD' THEN 'documents.attachments.write' ELSE NULL END;
 IF required IS NULL THEN RAISE EXCEPTION 'Invalid document action' USING ERRCODE='HD422';END IF;
 PERFORM purchase.require_access(required);
 SELECT document_type INTO typ FROM platform.documents WHERE company_id=core.current_company() AND id=doc AND deleted_at IS NULL AND platform.document_visible(doc);
 IF NOT FOUND THEN RAISE EXCEPTION 'Document unavailable' USING ERRCODE='HT404';END IF;
 IF typ IN('CRM_NOTE','CRM_BOARD','CRM_VISIT','CRM_DRAFT')THEN IF action NOT IN('READ','UPLOAD')THEN RAISE EXCEPTION 'CRM supports private attachments only' USING ERRCODE='HD422';END IF;PERFORM crm.require_crm_file(doc,action='UPLOAD');
 ELSIF typ='QUOTE' THEN
  SELECT customer_id INTO customer FROM sales.quotes WHERE company_id=core.current_company() AND id=doc;
  PERFORM sales.require_customer_access('sales.quotes.read',customer);
  IF action='EMAIL' THEN PERFORM purchase.require_access('sales.quotes.send');END IF;
 ELSIF typ='INVOICE' THEN
  SELECT customer_id INTO customer FROM sales.invoices WHERE company_id=core.current_company() AND id=doc;
  PERFORM sales.require_customer_access('sales.invoices.read',customer);
  IF action='EMAIL' THEN PERFORM purchase.require_access('sales.invoices.send');END IF;
 ELSIF typ='PURCHASE_ORDER' THEN
  PERFORM purchase.require_access('purchase.orders.read');PERFORM purchase.require_access('purchase.cost.read');
  IF action='EMAIL' THEN PERFORM purchase.require_access('purchase.orders.send');END IF;
 ELSIF typ='PICK' THEN
 IF action NOT IN('READ','UPLOAD') THEN RAISE EXCEPTION 'Warehouse handover supports private attachments only' USING ERRCODE='HD422';END IF;PERFORM inventory.require_access('inventory.picks.read',(SELECT o.warehouse_id FROM inventory.picks pk JOIN sales.orders o ON o.company_id=pk.company_id AND o.id=pk.order_id WHERE pk.company_id=core.current_company() AND pk.id=doc));
 ELSIF typ IN('SUPPLIER_BILL','SUPPLIER_CREDIT') THEN IF action NOT IN('READ','UPLOAD') THEN RAISE EXCEPTION 'Procurement document supports private attachments only' USING ERRCODE='HD422';END IF;PERFORM purchase.require_access(CASE WHEN typ='SUPPLIER_BILL' THEN 'purchase.bills.read' ELSE 'purchase.credits.read' END);
 ELSIF typ='CUSTOMER_STATEMENT'THEN
 IF action NOT IN('READ','PDF','EMAIL')THEN RAISE EXCEPTION 'Statement supports PDF and authorized mail only' USING ERRCODE='HD422';END IF;
 SELECT customer_id INTO customer FROM accounting.customer_statements WHERE company_id=core.current_company()AND id=doc;PERFORM sales.require_customer_access('accounting.statements.read',customer);PERFORM purchase.require_access('accounting.ledger.read');PERFORM purchase.require_access('accounting.reports.read');IF action='EMAIL'THEN PERFORM purchase.require_access('accounting.statements.send');END IF;
 ELSIF typ='OPERATING_REPORT'THEN
 IF action NOT IN('READ','EXPORT')THEN RAISE EXCEPTION 'Operating reports support controlled CSV export only' USING ERRCODE='HD422';END IF;
 PERFORM accounting.require_operating_report((SELECT kind FROM accounting.operating_report_runs WHERE company_id=core.current_company()AND id=doc));PERFORM purchase.require_access('reports.operating.export');
 ELSE RAISE EXCEPTION 'This document type has no file/output workflow yet' USING ERRCODE='HD422';END IF;
 RETURN typ;
END $$;

CREATE OR REPLACE FUNCTION platform.load_document_work(jid uuid,fence uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE j platform.document_jobs;f record;payload jsonb;attachments jsonb:='[]';BEGIN
 SELECT * INTO j FROM platform.document_jobs WHERE id=jid AND lease_token=fence AND lease_until>now() AND state='PROCESSING';
 IF NOT FOUND THEN RAISE EXCEPTION 'Lease unavailable' USING ERRCODE='HD409';END IF;
 PERFORM set_config('htt.company_id',j.company_id::text,true);PERFORM set_config('htt.actor_id',j.created_by::text,true);
 IF j.kind='SCAN'AND EXISTS(SELECT 1 FROM platform.documents WHERE company_id=j.company_id AND id=j.document_id AND document_type LIKE'CRM_%')THEN PERFORM platform.require_document_access(j.document_id,'UPLOAD');END IF;
 IF j.kind<>'SCAN' THEN PERFORM platform.require_document_access(j.document_id,j.kind);END IF;
 payload:=j.payload;
 IF j.kind='EMAIL' THEN
  IF NOT EXISTS(SELECT 1 FROM platform.documents WHERE company_id=j.company_id AND id=j.document_id AND version=j.source_version AND state IN('CONFIRMED','POSTED') AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Document version changed before email dispatch' USING ERRCODE='HD409';END IF;
  FOR f IN SELECT * FROM jsonb_array_elements_text(payload->'fileIds') LOOP
   attachments:=attachments||jsonb_build_array((SELECT jsonb_build_object('filename',a.filename,'content',replace(encode(b.body,'base64'),E'\n',''))
    FROM platform.file_assets a JOIN platform.files x ON x.company_id=a.company_id AND x.id=a.file_id JOIN platform.file_contents b ON b.company_id=x.company_id AND b.file_id=x.id
    WHERE a.company_id=j.company_id AND a.file_id=f.value::uuid AND a.document_id=j.document_id AND a.revoked_at IS NULL AND x.state='VERIFIED' AND x.sha256=encode(sha256(b.body),'hex')));
  END LOOP;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(attachments)x WHERE x='null'::jsonb) THEN RAISE EXCEPTION 'Mail attachment unavailable' USING ERRCODE='HD409';END IF;
  payload:=(payload-'fileIds')||jsonb_build_object('attachments',attachments);
 ELSIF j.kind='SCAN' THEN
  SELECT jsonb_build_object('content',replace(encode(b.body,'base64'),E'\n',''),'contentType',x.content_type) INTO payload
  FROM platform.file_assets a JOIN platform.files x ON x.company_id=a.company_id AND x.id=a.file_id JOIN platform.file_contents b ON b.company_id=x.company_id AND b.file_id=x.id
  WHERE a.company_id=j.company_id AND a.document_id=j.document_id AND a.file_id=(j.payload->>'fileId')::uuid AND a.revoked_at IS NULL AND x.state='PENDING' AND x.sha256=encode(sha256(b.body),'hex');
  IF payload IS NULL THEN RAISE EXCEPTION 'Pending file unavailable' USING ERRCODE='HD409';END IF;
 END IF;
 RETURN payload;
END $$;

CREATE OR REPLACE FUNCTION platform.finish_document_work(jid uuid,fence uuid,result text,error_code text,pdf bytea DEFAULT NULL,provider text DEFAULT NULL) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE j platform.document_jobs;fid uuid;filename text;BEGIN
 SELECT * INTO j FROM platform.document_jobs WHERE id=jid AND lease_token=fence AND lease_until>now() AND state='PROCESSING';
 IF NOT FOUND THEN RETURN false;END IF;
 IF result NOT IN('SUCCEEDED','RETRY','FAILED','UNKNOWN','REJECTED') OR error_code IS NOT NULL AND error_code!~'^[a-z0-9_]{1,80}$' THEN RAISE EXCEPTION 'Invalid work result' USING ERRCODE='HD422';END IF;
 PERFORM set_config('htt.company_id',j.company_id::text,true);PERFORM set_config('htt.actor_id',j.created_by::text,true);
 IF EXISTS(SELECT 1 FROM platform.documents WHERE company_id=j.company_id AND id=j.document_id AND document_type LIKE'CRM_%')THEN PERFORM crm.lock_mobile_head();END IF;
 SELECT*INTO j FROM platform.document_jobs WHERE id=jid AND lease_token=fence AND lease_until>now()AND state='PROCESSING'FOR UPDATE;IF NOT FOUND THEN RETURN false;END IF;
 IF j.kind='SCAN'AND EXISTS(SELECT 1 FROM platform.documents WHERE company_id=j.company_id AND id=j.document_id AND document_type LIKE'CRM_%')THEN
 BEGIN PERFORM platform.require_document_access(j.document_id,'UPLOAD');IF NOT EXISTS(SELECT 1 FROM platform.file_assets WHERE company_id=j.company_id AND file_id=(j.payload->>'fileId')::uuid AND revoked_at IS NULL)THEN result:='FAILED';error_code:='attachment_revoked';END IF;
 EXCEPTION WHEN insufficient_privilege OR SQLSTATE'HT404'OR SQLSTATE'HR409'THEN result:='FAILED';error_code:='document_access_changed';END;
 END IF;

 IF result='SUCCEEDED' AND j.kind IN('PDF','EXPORT') THEN
  IF j.kind='EXPORT'OR EXISTS(SELECT 1 FROM accounting.customer_statements WHERE company_id=j.company_id AND id=j.document_id)THEN PERFORM platform.require_document_access(j.document_id,j.kind);END IF;
  IF pdf IS NULL OR octet_length(pdf) NOT BETWEEN 8 AND 10485760 OR(j.kind='PDF'AND substring(pdf FROM 1 FOR 5)<>convert_to('%PDF-','UTF8'))OR(j.kind='EXPORT'AND substring(pdf FROM 1 FOR 3)<>decode('efbbbf','hex'))THEN RAISE EXCEPTION 'Invalid generated PDF' USING ERRCODE='HD422';END IF;
  fid:=gen_random_uuid();filename:=j.payload->>'filename';
  INSERT INTO platform.files(id,company_id,object_key,content_type,size_bytes,sha256,state,created_by) VALUES(fid,j.company_id,j.company_id::text||'/'||fid::text,CASE WHEN j.kind='PDF'THEN'application/pdf'ELSE'text/csv; charset=utf-8'END,octet_length(pdf),encode(sha256(pdf),'hex'),'VERIFIED',j.created_by);
  INSERT INTO platform.file_contents(company_id,file_id,body) VALUES(j.company_id,fid,pdf);
  INSERT INTO platform.file_assets(company_id,file_id,document_id,source_version,filename,kind) VALUES(j.company_id,fid,j.document_id,j.source_version,filename,CASE WHEN j.kind='PDF'THEN'PDF'ELSE'EXPORT'END);
  INSERT INTO platform.file_links(company_id,file_id,document_id,created_by) VALUES(j.company_id,fid,j.document_id,j.created_by);
 ELSIF j.kind='SCAN' AND result IN('SUCCEEDED','REJECTED') THEN
  fid:=(j.payload->>'fileId')::uuid;
  UPDATE platform.files SET state=CASE WHEN result='SUCCEEDED' THEN 'VERIFIED' ELSE 'REJECTED' END WHERE company_id=j.company_id AND id=fid AND state='PENDING';
 ELSIF result='SUCCEEDED' AND j.kind='EMAIL' AND (provider IS NULL OR length(provider) NOT BETWEEN 1 AND 200) THEN RAISE EXCEPTION 'Provider receipt required' USING ERRCODE='HD422';
 END IF;
 UPDATE platform.document_job_attempts SET finished_at=now(),result=finish_document_work.result,error_code=finish_document_work.error_code WHERE company_id=j.company_id AND job_id=j.id AND lease_token=fence;
 UPDATE platform.document_jobs SET state=CASE WHEN result='REJECTED' THEN 'FAILED' WHEN result='RETRY' AND attempts>=5 THEN 'FAILED' ELSE result END,
  output_file_id=coalesce(fid,output_file_id),provider_id=provider,last_error=error_code,
  completed_at=CASE WHEN result='SUCCEEDED' THEN now() END,available_at=now()+make_interval(secs=>least(900,15*power(2,attempts)::int)),lease_token=NULL,lease_until=NULL WHERE id=j.id;
 INSERT INTO platform.audit_events(company_id,actor_id,action,entity_type,entity_id,request_id,details)
  VALUES(j.company_id,j.created_by,'documents.work_finished','document_job',j.id,'document-worker',jsonb_build_object('kind',j.kind,'result',result,'errorCode',error_code,'attempt',j.total_attempts));
 RETURN true;
END $$;
CREATE FUNCTION crm.map_branches(p_filter jsonb)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE result jsonb;BEGIN PERFORM crm.require_mobile('crm.maps.read');
 WITH all_rows AS(SELECT b.id,b.customer_id,b.name,b.code,b.address_line1,b.suburb,b.state,b.postcode,b.country,b.version,cu.status AS customer_status,pa.legal_name AS customer_name,g.source,g.precision,g.place_id,g.expires_at,
 CASE WHEN g.branch_version=b.version AND(g.expires_at IS NULL OR g.expires_at>now())THEN g.latitude END AS latitude,CASE WHEN g.branch_version=b.version AND(g.expires_at IS NULL OR g.expires_at>now())THEN g.longitude END AS longitude,
 CASE WHEN g.branch_version=b.version AND(g.expires_at IS NULL OR g.expires_at>now())THEN'LOCATED'WHEN g.branch_id IS NOT NULL THEN'STALE'WHEN j.state IN('PENDING','PROCESSING','RETRY')THEN'PENDING'WHEN j.state='FAILED'THEN'FAILED'ELSE'UNLOCATED'END AS geocode_state,
 EXISTS(SELECT 1 FROM crm.collaboration_objects o WHERE o.company_id=b.company_id AND o.branch_id=b.id AND o.kind='BOARD'AND o.state='DISPLAYED')AS has_boards
 FROM crm.customer_branches b JOIN crm.customers cu ON cu.company_id=b.company_id AND cu.id=b.customer_id JOIN crm.parties pa ON pa.company_id=cu.company_id AND pa.id=cu.party_id LEFT JOIN crm.branch_geocodes g ON g.company_id=b.company_id AND g.branch_id=b.id LEFT JOIN crm.geocode_jobs j ON j.company_id=b.company_id AND j.branch_id=b.id AND j.branch_version=b.version
 WHERE b.company_id=core.current_company()AND b.active AND crm.mobile_customer_visible(b.customer_id)),filtered AS(SELECT*FROM all_rows r WHERE((p_filter->>'customerId')IS NULL OR r.customer_id=(p_filter->>'customerId')::uuid)AND((p_filter->>'state')IS NULL OR r.state=p_filter->>'state')AND((p_filter->>'status')IS NULL OR r.customer_status=p_filter->>'status')AND((p_filter->>'geocodeState')IS NULL OR r.geocode_state=p_filter->>'geocodeState')AND((p_filter->>'hasBoards')IS NULL OR r.has_boards=(p_filter->>'hasBoards')::boolean)AND((p_filter->>'q')IS NULL OR strpos(lower(concat_ws(' ',r.name,r.customer_name,r.suburb,r.postcode)),lower(p_filter->>'q'))>0)AND((p_filter->>'salesperson')IS NULL OR EXISTS(SELECT 1 FROM identity.customer_assignments a JOIN identity.memberships m ON m.company_id=a.company_id AND m.id=a.membership_id WHERE a.company_id=core.current_company()AND a.customer_id=r.customer_id AND m.user_id=(p_filter->>'salesperson')::uuid AND m.active))AND((p_filter->>'south')IS NULL OR r.latitude BETWEEN(p_filter->>'south')::numeric AND(p_filter->>'north')::numeric AND CASE WHEN(p_filter->>'west')::numeric<=(p_filter->>'east')::numeric THEN r.longitude BETWEEN(p_filter->>'west')::numeric AND(p_filter->>'east')::numeric ELSE r.longitude>=(p_filter->>'west')::numeric OR r.longitude<=(p_filter->>'east')::numeric END)),paged AS(SELECT*FROM filtered ORDER BY id LIMIT(p_filter->>'size')::int OFFSET(p_filter->>'offset')::int)
 SELECT jsonb_build_object('total',(SELECT count(*)FROM filtered),'items',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'customerId',r.customer_id,'name',r.name,'code',r.code,'addressLine1',r.address_line1,'suburb',r.suburb,'state',r.state,'postcode',r.postcode,'country',r.country,'version',r.version,'customerStatus',r.customer_status,'customerName',r.customer_name,'source',r.source,'precision',r.precision,'expiresAt',r.expires_at,'latitude',r.latitude,'longitude',r.longitude,'geocodeState',r.geocode_state,'hasBoards',r.has_boards,'attribution',CASE WHEN r.source='GOOGLE'AND r.latitude IS NOT NULL THEN'Google Maps'END,'mapProvider',CASE WHEN r.source='GOOGLE'AND r.latitude IS NOT NULL THEN'GOOGLE'END)ORDER BY id)FROM paged r),'[]'))INTO result;RETURN result;
END$$;
CREATE FUNCTION crm.guard_collab_identity()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN IF TG_OP='DELETE'OR OLD.state='DELETED'OR(NEW.id,NEW.company_id,NEW.kind,NEW.customer_id,NEW.branch_id,NEW.product_id,NEW.owner_id,NEW.created_at)IS DISTINCT FROM(OLD.id,OLD.company_id,OLD.kind,OLD.customer_id,OLD.branch_id,OLD.product_id,OLD.owner_id,OLD.created_at)THEN RAISE EXCEPTION 'CRM identity/final deletion is immutable' USING ERRCODE='23514';END IF;RETURN NEW;END$$;
CREATE TRIGGER collaboration_identity BEFORE UPDATE OR DELETE ON crm.collaboration_objects FOR EACH ROW EXECUTE FUNCTION crm.guard_collab_identity();
-- New app tables are read-only; every mutation goes through a scoped command.
DO $$DECLARE p record;BEGIN FOR p IN SELECT oid::regprocedure AS fn FROM pg_proc WHERE pronamespace='crm'::regnamespace AND(proname LIKE '%collab%'OR proname IN('validate_collab_data','validate_fix','sync_draft_registry','require_crm_file','emit_attachment','file_changed','require_branch','queue_geocode','geocode_view','retry_geocode','emit_geocode','set_branch_coordinates','claim_geocode','load_geocode','finish_geocode','map_branches'))LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',p.fn);END LOOP;END$$;
REVOKE ALL ON FUNCTION identity.seed_collaboration_roles(uuid)FROM PUBLIC;
GRANT SELECT ON crm.collaboration_objects,crm.collaboration_history,crm.collaboration_changes,crm.branch_geocodes,crm.geocode_jobs TO htt_app;
GRANT EXECUTE ON FUNCTION crm.collab_visible(uuid),crm.require_collab(uuid,boolean),crm.collab_json(uuid),crm.collab_history(uuid),crm.collab_command(uuid,text,uuid,uuid,text,bigint,jsonb),crm.collab_push(uuid,uuid,bigint,jsonb),crm.require_branch(uuid,boolean),crm.queue_geocode(uuid,bigint),crm.geocode_view(uuid),crm.retry_geocode(uuid),crm.set_branch_coordinates(uuid,bigint,numeric,numeric,text),crm.map_branches(jsonb)TO htt_app;
GRANT EXECUTE ON FUNCTION crm.claim_geocode(),crm.load_geocode(uuid,uuid),crm.finish_geocode(uuid,uuid,text,text,jsonb)TO htt_worker;

CREATE FUNCTION crm.prepare_branch_change(p_customer uuid)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM sales.require_customer_access('customers.write',p_customer);PERFORM crm.lock_mobile_head();PERFORM sales.require_customer_access('customers.write',p_customer);END$$;
CREATE FUNCTION crm.branch_changed()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.emit_geocode(NEW.id);RETURN NEW;END$$;
CREATE TRIGGER crm_branch_change AFTER INSERT OR UPDATE ON crm.customer_branches FOR EACH ROW EXECUTE FUNCTION crm.branch_changed();
REVOKE ALL ON FUNCTION crm.prepare_branch_change(uuid),crm.branch_changed()FROM PUBLIC;GRANT EXECUTE ON FUNCTION crm.prepare_branch_change(uuid)TO htt_app;

CREATE FUNCTION crm.require_collab_customer(p_customer uuid)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_mobile('crm.collaboration.read');IF p_customer IS NULL OR NOT crm.mobile_customer_visible(p_customer)THEN RAISE EXCEPTION 'Customer collaboration access denied' USING ERRCODE='42501';END IF;END$$;
REVOKE ALL ON FUNCTION crm.require_collab_customer(uuid)FROM PUBLIC;GRANT EXECUTE ON FUNCTION crm.require_collab_customer(uuid)TO htt_app;
